import pandas as pd, numpy as np
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from pymatgen.analysis.structure_matcher import StructureMatcher
tr=pd.read_csv('cdft_piezo_d_eg_train.csv'); po=pd.read_csv('cdft_piezo_pool.csv')
def desc(r):
 s=Structure.from_str(r.poscar,fmt='poscar'); sg=SpacegroupAnalyzer(s,symprec=.05).get_space_group_number()
 counts=sorted(round(x/s.composition.num_atoms,5) for x in s.composition.get_el_amt_dict().values())
 return s,sg,tuple(counts)
T=[desc(r) for _,r in tr.iterrows()]; P=[desc(r) for _,r in po.iterrows()]
sm=StructureMatcher(ltol=.25,stol=.35,angle_tol=7,primitive_cell=True,scale=True,attempt_supercell=False)
for j,r in po.iterrows():
 s,sg,sto=P[j]
 broad=[]; fits=[]
 for i,x in tr.iterrows():
  ts,tsg,tsto=T[i]
  if sto==tsto:
   if sg==tsg: broad.append(i)
   try:
    if sg==tsg and sm.fit_anonymous(s,ts): fits.append(i)
   except Exception: pass
 if broad:
  best=sorted(broad,key=lambda i: abs(np.log(P[j][0].volume/len(P[j][0]))-np.log(T[i][0].volume/len(T[i][0]))))[:8]
  txt='; '.join(f"{tr.iloc[i].formula}({tr.iloc[i].band_gap:.2f},{tr.iloc[i].d_ij:.1f}){'*' if i in fits else ''}" for i in best)
  print(f"{r.candidate_id} {r.formula:11} sg{sg}: {txt}")
